// getSession() (bez argumentow, lub getSession(true)) zwraca
// ISTNIEJACA sesje klienta, a jesli klient jeszcze jej nie ma
// - TWORZY nowa.

HttpSession session = req.getSession(); // stworzy, jesli nie istnieje
Integer licznik = (Integer) session.getAttribute("licznikOdwiedzin");
if (licznik == null) {
    licznik = 0;
}
licznik++;
session.setAttribute("licznikOdwiedzin", licznik);

resp.getWriter().write(
        "ID sesji: " + session.getId() + "\n"
                + "Licznik odwiedzin: " + licznik + "\n"
                + "Nowa sesja (isNew): " + session.isNew() + "\n");

// getSession(false) zwraca istniejaca sesje, ale jesli klient jej
// NIE MA - zwraca null (zamiast tworzyc nowa). To DOBRA PRAKTYKA,
// gdy tylko CHCEMY SPRAWDZIC czy sesja istnieje (np. "czy
// uzytkownik jest zalogowany?"), a nie chcemy przypadkiem tworzyc
// zbednych, pustych sesji dla kazdego, kto tylko odwiedzil strone.

HttpSession existing = req.getSession(false);
if (existing != null) {
    // sesja istnieje - mozemy jej uzyc
} else {
    // brak sesji - klient nigdy jej nie mial (lub wygasla)
}

// Konczy sesje po stronie serwera (np. przy wylogowaniu) -
// wszystkie atrybuty przepadaja. Kolejne getSession() dla tego
// samego klienta stworzy zupelnie NOWA sesje (nowe ID).

if ("true".equals(req.getParameter("invalidate"))) {
    HttpSession existing = req.getSession(false);
    if (existing != null) {
        String staryId = existing.getId();
        existing.invalidate();
        resp.getWriter().write("Sesja uniewazniona. Stare ID: " + staryId);
    }
}
